  if (stopping) return;
  stopping = true;
  if (reason !== 'completed') send({ type: 'interrupted', reason });
  if (process.platform !== 'win32') {
    try { process.kill(-process.pid, 'SIGKILL'); } catch {}
    process.exit(1);
  }
